const input = $input.first().json;
const contractVersion = '1.0';
const testMode = input.testMode !== false;
const correlationId = typeof input.correlationId === 'string' && /^[A-Za-z0-9._:-]{1,128}$/.test(input.correlationId) ? input.correlationId : crypto.randomUUID();
const fail = (code,message) => [{json:{ok:false,contractVersion,testMode,correlationId,error:{code,message}}}];
const allowed = new Set(['contractVersion','testMode','correlationId','channel','messageId','senderRef','text','receivedAt','attachments','metadata']);
if (Object.keys(input).some((key) => !allowed.has(key))) return fail('INVALID_REQUEST','Raw or unknown fields are not accepted');
if (input.contractVersion !== undefined && input.contractVersion !== contractVersion) return fail('UNSUPPORTED_CONTRACT','contractVersion must be 1.0');
if (typeof input.channel !== 'string' || !/^[a-z][a-z0-9._-]{1,31}$/.test(input.channel)) return fail('INVALID_CHANNEL','channel must be a safe adapter identifier');
if (typeof input.messageId !== 'string' || !/^[A-Za-z0-9._:-]{1,128}$/.test(input.messageId)) return fail('INVALID_MESSAGE_ID','messageId must be opaque and stable');
if (typeof input.senderRef !== 'string' || !/^[A-Za-z0-9._:-]{3,128}$/.test(input.senderRef)) return fail('INVALID_SENDER_REF','senderRef must be an opaque non-PII reference');
if (typeof input.text !== 'string' || input.text.trim().length < 1 || input.text.length > 12000) return fail('INVALID_TEXT','text must contain 1..12000 characters');
const receivedAt = new Date(input.receivedAt ?? Date.now());
if (Number.isNaN(receivedAt.getTime())) return fail('INVALID_TIME','receivedAt must be an ISO timestamp');
const attachments = input.attachments ?? [];
if (!Array.isArray(attachments) || attachments.length > 10 || attachments.some((item) => !item || typeof item.fileRef !== 'string' || !/^[A-Za-z0-9._:-]{3,128}$/.test(item.fileRef) || typeof item.mimeType !== 'string' || item.mimeType.length > 100)) return fail('INVALID_ATTACHMENTS','attachments may contain only fileRef and mimeType');
const metadata = input.metadata ?? {};
const metadataAllowed = new Set(['language','threadRef','replyToMessageId','sourceType']);
if (!metadata || Array.isArray(metadata) || typeof metadata !== 'object' || Object.keys(metadata).some((key) => !metadataAllowed.has(key)) || Object.values(metadata).some((value) => typeof value !== 'string' || value.length > 128)) return fail('INVALID_METADATA','metadata contains a disallowed or oversized field');
return [{json:{ok:true,contractVersion,testMode,correlationId,message:{messageKey:`${input.channel}:${input.messageId}`,channel:input.channel,messageId:input.messageId,senderRef:input.senderRef,text:input.text.trim(),receivedAt:receivedAt.toISOString(),attachments:attachments.map(({fileRef,mimeType}) => ({fileRef,mimeType})),metadata}}}];
